sketches.source:
setcpm(76/4)

// Four bars in G, then the whole song lifts a whole step
const lift = "<0 0 0 0 2 2 2 2>"

// Rolling piano: G, Em, C, D
piano: note("<[g2 d3 g3 b3 d4 b3 g3 d3] [e2 b2 e3 g3 b3 g3 e3 b2] [c3 g3 c4 e4 g4 e4 c4 g3] [d3 a3 d4 f#4 a4 f#4 d4 a3]>").add(lift)
  .s("triangle").timbre("soft").attack(.005).decay(.8).sustain(.1).release(.8).room(.4).gain(.26)

// She sings of somewhere else; the syllables carry the same weights as the notes
heroine: note("<[d4@3 e4 g4@4] [b4@3 a4 g4@2 e4@2] [e4@2 g4@2 c5@3 b4] [a4@6 ~@2]>").add(lift)
  .s("voice").syl("<[so@3 me de@4] [i@3 wa na@2 go@2] [oo@2 ta@2 ri@3 a] [ho@6 ~@2]>")
  .voicetype("soprano").mono(1).vglide(.1).attack(.08).release(.8).space("hall").gain(.3)

// The strings join on the second phrase
strings: note("<[g3,b3,d4] [g3,b3,e4] [g3,c4,e4] [f#3,a3,d4]>").add(lift).mask("<0 0 1 1 1 1 1 1>")
  .s("sawtooth").unison(4).detune(20).lpf(1800).attack(.8).sustain(.9).release(1.5).room(.6).gain(.12)
bass: note("<g1 e2 c2 d2>").add(lift).s("sine").attack(.05).sustain(.8).release(.6).gain(.32)

// A cymbal swell carries her up into the new key
swell: s("pink").mask("<0 0 0 1 0 0 0 0>").hpf(3000).attack(2.5).release(.3).gain(.05)

setcpm(120/4)

// The bows: the heroine's theme, then the company's kickline, then a last held chord
const heroine = note("<[d4@3 e4 g4@4] [b4@3 a4 g4@2 e4@2] [e4@2 g4@2 c5@3 b4] [a4@6 d5@2]>")
const company = note("<[g4@2 c5@2 e5@2 g5@2] [f5@2 d5 b4 d5@4] [a4@2 d5@2 f5@2 a5@2] [g5@4 e5@2 c5@2]>")
const last = note("[c4,e4,g4,c5]").slow(4)

// .once() plays each form a single time: twelve bars of bows, then silence
lead: form("A@4 B@4 C@4", heroine, company, last).once()
  .s("sawtooth").unison(3).detune(15).lpf(2400).lpenv(1.5).lpattack(.03)
  .attack(.03).sustain(.7).release(1).room(.5).gain(.2)
chords: form("A@4 B@4 C@4", note("<[g3,b3,d4] [g3,b3,e4] [g3,c4,e4] [f#3,a3,d4]>"), note("<[e3,g3,c4] [f3,g3,b3] [f3,a3,d4] [e3,g3,c4]>"), note("[e3,g3,c4]").slow(4)).once()
  .s("sawtooth").unison(4).detune(20).lpf(1600).attack(.2).sustain(.9).release(1.5).room(.6).gain(.12)
bass: form("A@4 B@4 C@4", note("<g1 e2 c2 d2>"), note("<c2 g1 d2 c2>"), note("c2").slow(4)).once()
  .s("sawtooth").lpf(500).attack(.02).sustain(.8).release(.6).gain(.3)

// The drums have their own layout: a fill into the last chord, then a single crash
drums: form("A@4 B@3 C D@4", s("bd ~ bd ~, ~ rim ~ rim"), s("bd ~ bd ~, ~ sd ~ sd, hh*8"), s("[lt lt mt mt] [ht ht ht ht]"), s("<[bd,cr] ~ ~ ~>")).once().gain(.45)

// The house rises to its feet, then the applause dies away
applause: s("crowd").slow(4).intensity(.8).gain(.22).enter(12).exit(20).fadeout(4, 16)
claps: s("cp*16?0.5").seed("bravo").pan(rand).gain(rand.range(.08, .2)).enter(12).exit(20).fadeout(4, 16)
